insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('nodal', 'intermediate', 'module', 'm01-the-column-pushes-back', 1, 'Hand the tubing a rate and a wellhead pressure. What does it hand back?', '["The bottomhole pressure that combination costs, which is a bill the well must pay rather than a delivery.", "The rate the string can carry at that wellhead pressure.", "A flowing bottomhole pressure the well is guaranteed to reach, because the string alone fixes the operating point.", "A wellhead rate corrected for the weight of the fluid standing above it."]'::jsonb, 0, 'The arithmetic runs opposite to reservoir intuition, since here a rate drives a pressure instead of a pressure driving a rate.'),
  ('nodal', 'intermediate', 'module', 'm01-the-column-pushes-back', 2, 'How is BONNY-7''s dead column figure of 2570 psia arrived at, and what does one subtraction settle?', '["Its friction end of 12560.087474 psia scaled back to zero rate.", "Its lowest sampled required pressure of 1477.003621 psia, taken at the bottom of the curve where the two terms cancel each other.", "Its 420 psia wellhead plus 2150 psi of weight, standing 170 psi under a reservoir pressure of 2740 psia.", "Its 420 psia wellhead added to the friction term carried at the lowest sampled rate."]'::jsonb, 2, 'No curve is needed for that verdict, so a well that starts itself can be recognised before any outflow sampling is done.'),
  ('nodal', 'intermediate', 'module', 'm01-the-column-pushes-back', 3, 'FORCADOS-3 sits on a 960 psia wellhead with 3350 psi of weight against 3720 psia of reservoir. What follows?', '["The well cannot flow at any rate, whatever the shape of its curve.", "Its dead column of 4310 psia stands 590 psi above the reservoir, so the column outweighs the reservoir at low rate.", "The well starts itself, because 3350 psi of weight is comfortably under the reservoir pressure it is compared against.", "The reservoir wins at low rate, so the curve is monotone rather than bent."]'::jsonb, 1, 'That verdict is about the low rate end alone, and the same well still ends below where it started once friction has taken over.'),
  ('nodal', 'intermediate', 'module', 'm01-the-column-pushes-back', 4, 'The classical balance carries three pressure losses. Which one is absent from this module and from Cullender and Smith?', '["Friction, which the caller must supply along with the injected curve.", "Hydrostatic, because the weight of the column is folded into the wellhead pressure term instead of being carried separately.", "The wellhead term, which is applied afterwards rather than inside the balance.", "Acceleration, since the published integrand carries an elevation group and a friction group and nothing else."]'::jsonb, 3, 'The omission bites where density changes fast, so a high velocity gas near the top of a string reads low by an amount never computed.'),
  ('nodal', 'intermediate', 'module', 'm01-the-column-pushes-back', 5, 'Why is the friction term a fair square law form while the gravity term is not an unbounded one?', '["Both terms are bounded above, gravity by the gravity constant and friction by the floor of the Moody factor, so neither can dominate a total.", "Gravity is capped by the gravity constant and spends its travel early, while the Moody factor barely moves once turbulent.", "Friction is bounded by the wellhead pressure and gravity is unbounded, which is why the required pressure eventually flattens out.", "The Moody factor falls fast enough with Reynolds number to cancel the velocity squared, so friction settles to a constant once fully turbulent."]'::jsonb, 1, 'That factor reads 0.02174609 at a Reynolds number of 50000 against 0.01476271 at 2000000, a small move across a wide span.'),
  ('nodal', 'intermediate', 'module', 'm01-the-column-pushes-back', 6, 'FORCADOS-3 asks 2552.129651 psia at 1037.09 stb/d and 2559.300006 psia at 2844.76 stb/d. What does the itemisation reveal?', '["Nearly the same total, but 1479.196441 psi of weight against 112.933210 at one rate and 749.572029 against 849.727978 at the other.", "Two rows with the same total always share the same cause.", "The lower rate row is the friction dominated one, so larger tubing is the cure there.", "The gravity term is the larger half at both rates, which is why one cure serves the whole curve."]'::jsonb, 0, 'A cure aimed at the wrong half is money spent on the smaller term, so the split matters more than the total does.'),
  ('nodal', 'intermediate', 'module', 'm01-the-column-pushes-back', 7, 'Friction overtakes gravity at 968.379388 stb/d on BONNY-7, yet the bottom of its curve sits at 627.069742 stb/d. Why do they differ?', '["The crossover was read off a coarser sampling than the bottom was.", "The bottom is quoted at the finely sampled resolution while the crossover is quoted at the sampled one, so the gap is an artefact of resolution alone.", "At the bottom the gravity term has fallen to exactly half the required pressure, which is the same statement as the two terms matching.", "A minimum is where the two slopes cancel, and that happens well before the two values themselves match each other."]'::jsonb, 3, 'FORCADOS-3 repeats it, crossing over at 2718.933018 stb/d with its bottom at 1843.619418 stb/d.'),
  ('nodal', 'intermediate', 'module', 'm01-the-column-pushes-back', 8, 'Why is the dry gas column the only outflow the engine owns, with every oil well supplied by the caller?', '["Oil wells are rare enough that the engine leaves them out.", "A black oil traverse would run too slowly inside a node solver, so it is pushed out to the caller for speed.", "Cullender and Smith needs nothing beyond a compressibility factor, so it is honestly self-contained.", "The engine can only carry a required pressure that rises throughout, and a gas column has no gravity limb to fall along."]'::jsonb, 2, 'A black oil traverse needs correlations, viscosities, a flow pattern map and holdup, and the Suite marches four defensible methods for that one job.'),
  ('nodal', 'intermediate', 'module', 'm01-the-column-pushes-back', 9, 'What does taking the outflow as an injected function buy the caller beyond avoiding a hardcoded correlation?', '["Faster evaluation, since a supplied function skips the internal march.", "It lets the engine cross check the supplied traverse against its own dry gas column and warn when the two disagree.", "The curve can be an instrument, so the solver becomes checkable by arithmetic against a residual of known shape.", "It removes the need to state a wellhead pressure or a tubing size, since an injected curve carries both inside itself already."]'::jsonb, 2, 'The exact parabola golden reads 770.000000 psi at 100.0000 stb/d and -40.000000 psi at 1000.0000 stb/d on an open flow of 2000.000000 stb/d.'),
  ('nodal', 'intermediate', 'module', 'm01-the-column-pushes-back', 10, 'What is the price of taking the outflow curve as an input, and where does it fall on the caller?', '["Nothing, since the solver rejects any curve it cannot reproduce.", "The solver runs more slowly, because an injected callable is evaluated once for every grid point rather than being tabulated.", "The wellhead pressure has to be restated, since injection discards it.", "You must bring a curve and nothing validates it, so one built on the wrong pressure basis is solved as confidently as a right one."]'::jsonb, 3, 'Two consumers can disagree about one well while each stays internally consistent, and a curve on the wrong flow regime looks the same as a right one.'),
  ('nodal', 'intermediate', 'module', 'm01-the-column-pushes-back', 11, 'What object is a tubing curve, and what exactly is the minimum reported alongside it?', '["A finite list of rate and pressure pairs, with the minimum a reduction over the sampled rows rather than a feature.", "A continuous function with an analytic bottom solved for exactly.", "A fitted polynomial through the sampled rows, whose minimum is found by setting the derivative of that fit to zero.", "A pair of curves, one for weight and one for friction, minimised together."]'::jsonb, 0, 'A reduction always returns a real row, which is why the golden dry gas curve still reports one despite rising throughout.'),
  ('nodal', 'intermediate', 'module', 'm01-the-column-pushes-back', 12, 'Why does the sampling begin at 4.324444 stb/d on BONNY-7 instead of at zero rate?', '["Zero rate falls outside the reservoir''s own sampled window, and the tubing is sampled on the axis the inflow hands it.", "Most outflow models are singular at zero, so the left end is put at one thousandth of the rate bound instead.", "The engine reserves the zero rate row for the dead column figure, which is computed separately and inserted at the left end.", "Rates under a few stb/d fall below the grid resolution the node solver carries, so those rows are ones no scan can land on."]'::jsonb, 1, 'That end lands slightly under the dead column, 2545.501142 psia against 2570 psia, and 4293.189726 against 4310 psia on FORCADOS-3.'),
  ('nodal', 'intermediate', 'module', 'm01-the-column-pushes-back', 13, 'The rate bound of a tubing curve is the absolute open flow. What does the tubing inherit as a result?', '["Its vertical axis, which is then set by the reservoir pressure.", "Nothing at all, because a bound is only a stopping point and leaves the sampled rows themselves untouched.", "Its sample count, which the inflow family fixes at 37 points.", "Its horizontal axis, so recalibrating the reservoir redraws the curve at a different spacing with no tubing having moved."]'::jsonb, 3, 'BONNY-7 carries 37 points, FORCADOS-3 65 and the published golden dry gas 25, so the counts differ case by case.'),
  ('nodal', 'intermediate', 'module', 'm01-the-column-pushes-back', 14, 'BONNY-7 reports a bottom at 604.341111 stb/d and 1477.003621 psia, against 627.069742 stb/d and 1476.243252 psia when resampled finely. Read the gap.', '["Both figures move by a similar proportion under refinement, since a finer sampling shifts the whole curve and not one row of it.", "Tens of stb/d in rate but under a psi in pressure, because a minimum has zero slope and the curve is flat around it.", "The rate is the reliable half and the pressure the fragile one, so a design document can safely quote the rate without qualification.", "The gap is numerical noise, since a minimum belongs to the curve itself rather than to the sampling that happened to report it."]'::jsonb, 1, 'FORCADOS-3 shows the same shape of gap, -31.814966 stb/d in rate against 0.25586360 psi in pressure.'),
  ('nodal', 'intermediate', 'module', 'm01-the-column-pushes-back', 15, 'BONNY-7 asks 1617.153368 psia at 964.35 stb/d, which looks comfortable under 2740 psia. What is wrong with that comparison?', '["Nothing, provided the wellhead pressure was entered as psia.", "The outflow figure is quoted at the sampled resolution rather than the fine one, so it is about a psi low before the comparison even starts.", "The 2740 psia is what the reservoir holds at zero rate, not while it delivers the rate that outflow figure assumed.", "The comparison inverts the residual, since the engine subtracts the required pressure from the delivered one, not the reverse."]'::jsonb, 2, 'At 1924.38 stb/d the same well asks 3140.705429 psia, which is above the static pressure altogether.'),
  ('nodal', 'intermediate', 'module', 'm02-the-j-shape', 1, 'Both teaching wells give a J shaped outflow curve. What produces that shape?', '["A single correlation fitted to the shape of measured curves.", "A friction term that falls at low rate and then rises again once the flow in the string turns from laminar to fully turbulent.", "A falling gravity term added to a friction term growing as the square of rate, so the sum cannot be monotone.", "A gravity term that is itself J shaped, so the friction term merely raises the whole curve without altering its shape."]'::jsonb, 2, 'Neither column is J shaped on its own, which is why the assembly table on BONNY-7 is worth reading term by term.'),
  ('nodal', 'intermediate', 'module', 'm02-the-j-shape', 2, 'BONNY-7 carries a lightening constant of 375 stb/d and FORCADOS-3 one of 820 stb/d. What does that constant set?', '["The rate at which the weight of the column has fallen to half its dead value, so it sets the width of the falling limb.", "The rate above which the column can no longer be lifted at all.", "The rate at which the friction term finally overtakes the gravity term, which is why the two wells turn at such different places on their axes.", "The lowest rate the sampling is allowed to start at."]'::jsonb, 0, 'Most of the difference between the two left limbs is that one constant, since the gravity form is bounded by its gravity constant either way.'),
  ('nodal', 'intermediate', 'module', 'm02-the-j-shape', 3, 'BONNY-7 demands 2545.501142 psia at 4.32 stb/d and 2198.309991 psia at 1444.36 stb/d, similar heights on a chart. Why are they not similar states?', '["The first was read off a sampled row while the second was interpolated between two rows, so only one of the pair is exact.", "The lower of the two is closer to the reservoir pressure.", "The first sits above the erosional ceiling of the 2.875 in bore, so it is not a state the completion would survive even briefly.", "The first is 0.99999437 gravity and an hour from dead, while the second is 0.24919685 gravity and pushes back on a disturbance."]'::jsonb, 3, 'Reading a low demand as good news without asking which limb produced it is the standing mistake of the falling limb.'),
  ('nodal', 'intermediate', 'module', 'm02-the-j-shape', 4, 'Why is the falling limb of the outflow curve the dangerous half?', '["Because the pressures on it are the highest anywhere on the curve.", "Adding rate reduces the demand, so a fall in rate raises it and suppresses the rate further with nothing restoring.", "Because the sampling is coarsest there, so the demand read off it carries the largest error of anywhere on the curve.", "Because friction is unmodelled below the crossover rate."]'::jsonb, 1, 'The limb looks attractive for the same reason it is unsafe, since the demand it shows is the lowest on the curve.'),
  ('nodal', 'intermediate', 'module', 'm02-the-j-shape', 5, 'A dry gas well has no falling limb at all. Why not?', '["Nothing in the Cullender and Smith march lightens with rate, so the gas column keeps its weight while friction only grows.", "The gas curve is sampled over far too narrow a window of rate for a falling half to appear anywhere inside the plotted range.", "The march is solved for pressure rather than for rate, so its curve is plotted the other way round and its falling half is hidden.", "The gravity term is deliberately suppressed in the gas construction."]'::jsonb, 0, 'The published golden gas curve rises from 952.986300 psia to 1842.190804 psia, so any bend in a real gas well is liquid in the pipe.'),
  ('nodal', 'intermediate', 'module', 'm02-the-j-shape', 6, 'A 2.992 in string at 6 MMscf/d carries a friction group of 0.00142657 while a 2.441 in string at 4 MMscf/d carries 0.00182455. How does the higher rate cost less?', '["The Moody factor collapses at the larger bore.", "The larger string is turbulent while the smaller one is not.", "The group divides by the fifth power of the bore, so half an inch of extra diameter outweighs half as much again in rate.", "The published group divides by the square of the bore, and the two effects happen to cancel over this particular pair of cases."]'::jsonb, 2, 'Between 4 and 9 MMscf/d in one bore the Moody factor only moves from 0.01481660 to 0.01455199, so diameter does nearly all of the work.'),
  ('nodal', 'intermediate', 'module', 'm02-the-j-shape', 7, 'FORCADOS-3''s friction term reaches only 1796.138365 psi while BONNY-7''s reaches 11968.524642 psi. What follows about the two curves?', '["The larger of the two terms proves that BONNY-7 has been completed on a string too small for the rates it is asked to make.", "The modest term is still the entire reason FORCADOS-3 turns at all, so a friction number means nothing without its rate.", "FORCADOS-3 is a gravity dominated well throughout, so its curve has no rising limb and the reported bottom is its left edge.", "The two wells cannot be compared because their coefficients differ."]'::jsonb, 1, 'Most of BONNY-7''s rising limb is arithmetic about states a 2740 psia reservoir could never reach.'),
  ('nodal', 'intermediate', 'module', 'm02-the-j-shape', 8, 'FORCADOS-3''s friction overtakes its gravity at 2718.933018 stb/d, yet its curve bottoms at 1843.619418 stb/d. Why does the bottom come first?', '["The crossover was read off a coarser grid than the bottom.", "The gravity term is bounded, so it leaves the slope well before it leaves the pressure it charges.", "A minimum sits where the two terms are equal, and the reported bottom is displaced by the sampling.", "A minimum is where the two slopes cancel, and the gravity share at that bottom is still 0.75175383 of the bill."]'::jsonb, 3, 'Setting a loading floor at the crossover rather than the bottom puts it hundreds of stb/d too high on both teaching wells.'),
  ('nodal', 'intermediate', 'module', 'm02-the-j-shape', 9, 'How does the module arrive at the minimum it reports beside a tubing curve?', '["It samples the outflow at a list of rates and returns the smallest pressure found together with the rate it was found at.", "It differentiates the sum of the two terms analytically and solves for the rate at which the resulting slope crosses through zero.", "It fits a parabola through the three lowest sampled rows and reports the vertex of that fit, which is why the pair is quoted to six figures.", "It bisects between the gravity limb and the friction limb."]'::jsonb, 0, 'The outflow arrives as an arbitrary callable with no promise of smoothness, so there is no derivative available to take.'),
  ('nodal', 'intermediate', 'module', 'm02-the-j-shape', 10, 'Resampling FORCADOS-3 finely moves its bottom by 31.814966 stb/d but its minimum pressure by only 0.25586360 psi. Why is that split guaranteed rather than lucky?', '["The pressure is quoted to fewer significant figures than the rate is, so rounding hides the smaller of the two moves.", "The sampling is denser in pressure than in rate on this well, since rows spaced evenly in pressure crowd near the bottom.", "The curve is flat where its slope is zero, so a large error in position along it buys a tiny error in height.", "The pressure is evaluated exactly at each sampled row while the rate is interpolated between rows, which is the whole of the difference."]'::jsonb, 2, 'The same flatness that makes the reported pressure robust is what makes the reported rate fragile, so no refinement of the grid trades one for the other.'),
  ('nodal', 'intermediate', 'module', 'm02-the-j-shape', 11, 'BONNY-7''s sampled bottom reads 604.341111 stb/d against a finely sampled 627.069742 stb/d. What does that gap forbid?', '["Any use of the sampled figure in a report at all.", "Comparing that bottom with a bottom taken from a different well.", "Quoting the minimum pressure alongside it, since that pressure inherits the same uncertainty the rate carries.", "A design margin narrower than the resolution of the curve, since a floor just above the sampled figure sits below the true turn."]'::jsonb, 3, 'State the sample count with the pair, because without it nobody downstream can tell whether the rate is exact or sits in a band tens of stb/d wide.'),
  ('nodal', 'intermediate', 'module', 'm02-the-j-shape', 12, 'BONNY-7 runs 2545.501142 psia at its loaded end to 1476.243252 psia at its bottom and on to 12560.087474 psia, while FORCADOS-3 runs 4293.189726 to 2348.191408 to 3310.421637 psia. What does that depth measure?', '["The quality of the sampling behind each of the two curves, since a deeper bottom is simply one that a denser grid managed to resolve.", "The distance each well sits from its own erosional ceiling, since a deeper bottom leaves more velocity headroom in the string.", "The margin each well holds against its reservoir pressure, which is why the deeper curve is the safer of the two to produce hard.", "The size of the restoring force, so the shallow well pushes back weakly on a disturbance in rate and wanders."]'::jsonb, 3, 'FORCADOS-3 ends below where it started, so its rising limb never buys back what the falling limb gave away.'),
  ('nodal', 'intermediate', 'module', 'm02-the-j-shape', 13, 'BONNY-7''s bottom sits at 627.069742 stb/d on an axis running to 4324.444444 stb/d, sampled at 37 points, while FORCADOS-3''s sits at 1843.619418 stb/d on 4135.949669 stb/d at 65 points. What limits the comparison?', '["The axis and the sample count both came from the inflow, so the smoother of the two pictures is a fact about the plot.", "Nothing, since the two rate bounds are almost the same length.", "The two wells carry different wellhead pressures, so the curves compare only once rebased to a common one.", "The bottoms were found by different methods on the two wells."]'::jsonb, 0, 'Most of BONNY-7''s range lies on its rising limb and much more of FORCADOS-3''s on its falling one, which is the reading worth taking.'),
  ('nodal', 'intermediate', 'module', 'm02-the-j-shape', 14, 'BONNY-7''s screen gives erosional velocities of 13.867505, 17.334381 and 24.268134 ft/s. Why is a single erosional limit not usable on its own?', '["Because the velocities were computed at a mixture density that nobody stated alongside them, so the conversion to a rate is not reproducible.", "Because the tubing curve already carries a velocity ceiling of its own, so an external limit would double count the same constraint.", "Each figure belongs to one empirical constant, C 100, C 125 or C 175, and the limit moves with the choice made.", "Because an erosional limit is written for the flowline and its elbows rather than for a vertical string, where velocity is lower."]'::jsonb, 2, 'Those three velocities convert to 9620.5002, 12025.6252 and 16835.8753 bbl/d in situ, a spread wide enough to change a completion decision.'),
  ('nodal', 'intermediate', 'module', 'm02-the-j-shape', 15, 'The tubing curve alone cannot say which side of its bottom a well is sitting on. What else is needed, and why does the side matter?', '["The sample count, because the side is decided by grid resolution.", "The reservoir''s own curve, because right of the bottom a disturbance is pushed back and left of it the disturbance grows.", "The erosional constant, because the side is decided by whether the well sits above or below its velocity ceiling.", "Nothing further, since the bottom itself names the rate the well makes."]'::jsonb, 1, 'Nothing on a tubing curve is a rate the well produces, and the far right of it is an evaluation of a state no reservoir on either teaching well could reach.'),
  ('nodal', 'intermediate', 'module', 'm03-what-moves-the-curve', 1, 'Raising the wellhead pressure by 70 psia does what to a tubing curve?', '["It lifts the demand most at low rate, where the column is heaviest.", "It lifts the demand by exactly 70 psi at every rate, because that term is additive and knows nothing about rate.", "It lifts the demand most at high rate, since the extra back pressure has to be carried through a friction term that is already growing as the square of rate.", "It lifts the curve by an amount that depends on which side of its bottom the well happens to be sitting on at the time."]'::jsonb, 1, 'BONNY-7''s dead column runs 2430, 2500, 2570 and 2640 psia across wellhead pressures of 280, 350, 420 and 490 psia, one step for one step.'),
  ('nodal', 'intermediate', 'module', 'm03-what-moves-the-curve', 2, 'Swept across wellhead pressures of 280, 350, 420 and 490 psia, BONNY-7 reports a minimum rate of 627.069742 stb/d every time. Why is the rate fixed?', '["The sampling grid is anchored to the same list of rates each run.", "The gravity and friction constants were held while only the wellhead moved.", "The minimum is found by a reduction over rows, and a reduction can only ever return one of the rates that was actually put into it.", "What was added has zero slope, so the slope at every rate is untouched and the rate where it crosses zero is untouched with it."]'::jsonb, 3, 'FORCADOS-3 does the same, holding 1843.619418 stb/d across all four of its wellhead pressures while its minimum pressure walks up in even steps.'),
  ('nodal', 'intermediate', 'module', 'm03-what-moves-the-curve', 3, 'A well is choked back at surface and later loads up. What did the choking actually do?', '["It raised the demand at every rate without moving the loading threshold, since the bottom of the curve did not relocate.", "It moved the loading threshold out to a higher rate, which is why a well that was stable before the choke change is loading now.", "It moved the loading threshold down to a lower rate.", "It changed nothing about the well at all, because the curve is rigid under a wellhead change and a rigid shift cannot alter an operating point."]'::jsonb, 0, 'Friction still overtakes gravity at 968.379388 stb/d on BONNY-7 whatever the separator is doing, and the gravity share is still 0.12887773 at 1924.38 stb/d.'),
  ('nodal', 'intermediate', 'module', 'm03-what-moves-the-curve', 4, 'A gauge reading is typed into the wellhead pressure field without conversion. What does that error look like on the finished curve?', '["A curve wrong only near the loaded end of the axis.", "A curve whose error grows with rate as the friction term amplifies it.", "A curve wrong by the same amount at every rate, which never shrinks and never cancels, so it still looks perfectly reasonable.", "A curve whose bottom has moved to a rate the well will never see, which is the tell that lets a reviewer catch the mistake before it is reported."]'::jsonb, 2, 'Every pressure in this module is psia and the module does not convert, so nothing downstream will flag the substitution.'),
  ('nodal', 'intermediate', 'module', 'm03-what-moves-the-curve', 5, 'The module asks for a wellhead pressure. Which pressure is it, and which one is commonly put there by mistake?', '["The pressure at the sandface, and a datum corrected reservoir pressure.", "The pressure at the top of the string, and a separator pressure sitting downstream of a choke and a flowline is the usual substitute.", "The average of the tubing head and casing head pressures.", "The pressure at the top of the string, and the casing head pressure taken on the annulus is the usual substitute at a gas lifted completion."]'::jsonb, 1, 'Choke and flowline losses appear nowhere in this curve, so a separator pressure understates the demand at every rate and does so silently.'),
  ('nodal', 'intermediate', 'module', 'm03-what-moves-the-curve', 6, 'Why is diameter the strongest lever a designer holds over the friction half of an outflow curve?', '["The published friction group divides by the fifth power of the inside diameter, so a small change of bore moves it a long way.", "Because the Moody factor is proportional to the bore.", "Because the friction group divides by the cube of the diameter while the gravity term is unaffected by the bore of the string at all.", "Because a larger bore lowers the Reynolds number into the laminar range."]'::jsonb, 0, 'A 2.992 in string at 6 MMscf/d carries 0.00142657 against a 2.441 in string at 4 MMscf/d on 0.00182455, so the higher rate costs less.'),
  ('nodal', 'intermediate', 'module', 'm03-what-moves-the-curve', 7, 'Halving BONNY-7''s friction constant from 0.00064 to 0.00032 takes its minimum from 1476.243252 psia to 1309.348403 psia. What else did it do?', '["It left the bottom where it was, at 627.069742 stb/d.", "It pulled the bottom back to a lower rate, which widens the band of the rising limb the well can safely be produced on.", "It raised the demand at the loaded end of the axis, which is the part of the curve a declining well will spend its last years sitting on.", "It slid the bottom from 627.069742 stb/d out to 845.667814 stb/d, so the loading threshold moved against the well."]'::jsonb, 3, 'That sentence is the field rule that oversized tubing loads up, since a rate on the rising limb of the tighter string can sit on the falling limb of the roomier one.'),
  ('nodal', 'intermediate', 'module', 'm03-what-moves-the-curve', 8, 'The friction constant in this instrument is a pure friction lever. Why does that understate what a bigger string really does?', '["A real bore change also moves the wellhead pressure the separator can hold.", "A real bore change alters the reservoir''s inflow curve too.", "A real bore change alters velocity, then slip, then holdup, so it changes the weight of the column as well as its wall loss.", "A real bore change moves the Moody factor more than the fifth power term does, so the friction size is wrong too."]'::jsonb, 2, 'The instrument gets the direction of the loading risk right by half the mechanism, since the heavier column at a given rate is a second and independent reason.'),
  ('nodal', 'intermediate', 'module', 'm03-what-moves-the-curve', 9, 'Water cut moves both constants in the gravity term. Which way does each move, and why?', '["Both fall, since produced water is less compressible than oil.", "Both rise: water is heavier than oil, and it carries no solution gas, so the column needs more rate to shed the same proportion of weight.", "The gravity constant rises and the lightening constant falls.", "The gravity constant rises while the lightening constant is untouched, since the gas that lightens a column comes from the oil."]'::jsonb, 1, 'The slower lightening is the effect that catches people, since only the extra weight is usually allowed for.'),
  ('nodal', 'intermediate', 'module', 'm03-what-moves-the-curve', 10, 'Swept across lightening constants of 187.50, 375.00, 750.00 and 1500.00 stb/d, BONNY-7 reports minimum rates of 561.403918, 627.069742, 646.294276 and 581.492476 stb/d. What should a reader take from that?', '["The rate column turns inside the range, so the pressure column is the honest signal for this particular lever.", "The sweep is too coarse and the turn is a sampling artefact.", "The rate column is monotone once the figures are rounded sensibly, and the apparent turn is an artefact of quoting them to six figures.", "The lever has no effect on the threshold worth reporting, so only the pressure column ever needs to be carried forward."]'::jsonb, 0, 'Raising the constant lifts the bottom monotonically in pressure while making the decline gentler, and where the rising friction term offsets that is not monotone.'),
  ('nodal', 'intermediate', 'module', 'm03-what-moves-the-curve', 11, 'A colleague asks this instrument what BONNY-7 does at 40 per cent water cut. What is the answer?', '["Sweep the friction constant, since water is the rougher phase and a wetter column drags harder on the wall than an oil column does.", "Read the answer off the gravity share at the rate bound, since that share is what a change of water cut moves and the curve follows it.", "Run the sweep at each of the four lightening constants and interpolate, since the mapping from water cut to the constant is close enough to linear over that band.", "There is no water cut input, only two constants, and nothing in the module maps a percentage onto either of them."]'::jsonb, 3, 'That mapping needs densities at conditions, a solution gas oil ratio, formation volume factors and a holdup correlation, which the module declines to own.'),
  ('nodal', 'intermediate', 'module', 'm03-what-moves-the-curve', 12, 'Lift gas lightens a column and roughens it with the same gas at the same time. How does BONNY-7 show both halves?', '["Only the lightening half appears in the reported minimum, since the friction penalty is second order at the rates this well is produced at.", "Both halves lower the demand, since a lighter column and a rougher wall each cut the pressure the string asks for, one by more than the other.", "Halving the lightening constant gives 1159.998265 psia and doubling the friction constant gives 1656.374688 psia, opposite signs.", "Halving the lightening constant and doubling the friction constant move the demand the same way, so the two effects reinforce rather than compete."]'::jsonb, 2, 'FORCADOS-3 agrees, its 2348.191408 psia falling to 1912.118951 psia and rising to 2608.483199 psia under the equivalent pair.'),
  ('nodal', 'intermediate', 'module', 'm03-what-moves-the-curve', 13, 'Why must the response of a real well to more lift gas eventually turn?', '["The lightening has a budget and decays with diminishing returns, while the friction it buys has no ceiling at all.", "Because the injection valve reaches its own capacity first, at which point no further gas can be put into the string.", "Because the friction term is linear in rate while the lightening is quadratic, so the two cross at a rate that is fixed by the string.", "Because the reservoir curve flattens once the drawdown grows large enough for turbulent skin to dominate the inflow, so extra lift buys nothing."]'::jsonb, 0, 'BONNY-7 sheds from 2125.489174 psi at 4.32 stb/d to 601.970606 psi by 964.35 stb/d and then needs the whole remaining axis to reach 171.562832 psi.'),
  ('nodal', 'intermediate', 'module', 'm03-what-moves-the-curve', 14, 'BONNY-7''s gravity share is 0.12887773 at 1924.38 stb/d while FORCADOS-3''s is still 0.53444210 at 2586.52 stb/d. Which well is the candidate for lift gas?', '["BONNY-7, because its lower share leaves more room to improve.", "FORCADOS-3, because lift gas attacks the gravity term and that term is still most of its bill through the middle of the axis.", "Neither, since the gravity share diagnoses tubing size and says nothing about response to injected gas.", "Both equally, since the two shares were read at different rates and compare only when taken at one common rate."]'::jsonb, 1, 'On BONNY-7 the gas would attack a term that is already small while adding to one that is already large, and its dead column of 2570 psia restarts the well anyway.'),
  ('nodal', 'intermediate', 'module', 'm03-what-moves-the-curve', 15, 'Why can a design change to an outflow curve almost never be reported honestly as a single number?', '["Because the module refuses to report a single figure at all.", "Because every lever has to be swept at four values before it can be quoted.", "It usually moves the level of the curve and the rate of its bottom at once, and often in directions that disagree.", "Because the two effects are always equal and opposite, so one number reports only their difference."]'::jsonb, 2, 'Only a change additive in pressure and blind to rate moves the level alone, and the wellhead pressure is the one lever of that kind.'),
  ('nodal', 'intermediate', 'module', 'm04-the-gas-column', 1, 'Why is dry gas the single outflow column the engine ships with, when every other column is left to the caller?', '["It is the commonest completion the Suite is asked about.", "It is single phase, so its density needs only a compressibility factor and its wall loss only a friction factor.", "It is the cheapest column to evaluate, so it is the only one that can be afforded inside a node solver that calls the outflow many times over.", "It is the only column whose bottomhole pressure can be written in closed form."]'::jsonb, 1, 'Both of those pieces are published and gate tested, whereas holdup and a flow pattern are correlated rather than derived.'),
  ('nodal', 'intermediate', 'module', 'm04-the-gas-column', 2, 'What happens inside the node solver when no outflow callable is handed to it at all?', '["It refuses the run and reports the well as dead.", "It builds a black oil traverse from whichever of the four Suite correlations best matches the stated fluid properties.", "It reuses the inflow family, reflected about the reservoir pressure.", "It falls back on a dry gas column solved by Cullender and Smith, which is the one outflow model it owns."]'::jsonb, 3, 'That fallback is silent, so an outflow study can be run on the wrong physics simply because the injected curve was never wired up.'),
  ('nodal', 'intermediate', 'module', 'm04-the-gas-column', 3, 'Why can the built-in column never produce the J shape that an oil outflow curve shows?', '["The gas is already gas, so raising the rate raises friction and leaves the weight of the column alone.", "The sampling is too coarse at 25 points to resolve a bottom.", "The engine deliberately suppresses the bend, because a J shaped gas curve would give the node solver two crossings to choose between and no rule for picking one.", "The friction term is omitted from the gas balance entirely."]'::jsonb, 0, 'Lightening with rate is a liquid phenomenon, which is why that curve rises monotonically from 952.986300 psia to 1842.190804 psia.'),
  ('nodal', 'intermediate', 'module', 'm04-the-gas-column', 4, 'The golden dry gas curve reports a minimum of 952.986300 psia at 13.289296 Mscf/d. What is that figure?', '["A genuine bottom, sitting at a thousandth of the rate bound.", "An extrapolation below the sampled window, taken down to the wellhead pressure of the string.", "The lowest sampled rate rather than a physical bottom, which the engine flags, since a reduction always returns a row.", "The rate at which the friction term first overtakes the weight of the column, which is where a gas bottom always sits."]'::jsonb, 2, 'The signature is that it sits at the first sample and moves by exactly one sample spacing when only the sample count is changed.'),
  ('nodal', 'intermediate', 'module', 'm04-the-gas-column', 5, 'What is the defining relation that Cullender and Smith exists to satisfy?', '["A weight per foot multiplied by the true vertical depth.", "An integral of a function of pressure from the wellhead down to the shoe equals 18.75 times gas gravity times measured depth.", "A balance between the wellhead pressure and the friction group, evaluated once at the average pressure and average temperature of the string.", "A sum of a gravity term and a friction term, each read from a published chart."]'::jsonb, 1, 'Targets therefore scale by depth and gravity alone, so three goldens on 8000 ft at 0.65 gravity all aim at 97500.0000 psi units.'),
  ('nodal', 'intermediate', 'module', 'm04-the-gas-column', 6, 'Why must the method march station by station instead of being rearranged for the answer?', '["The integrand depends on the compressibility factor, which depends on the very pressure being solved for.", "The temperature profile is unknown until the march has finished.", "The unknown appears inside the friction group, and a friction group that contains its own answer cannot be evaluated in one pass at any depth.", "Simpson''s rule needs an even number of sub-intervals, so an integral of this shape has to be built up interval by interval."]'::jsonb, 0, 'Each station carries its own temperature from a straight line in measured depth, and each interval closes by fixed point iteration to a thousandth of a psi.'),
  ('nodal', 'intermediate', 'module', 'm04-the-gas-column', 7, 'A converged march reproduces its own defining relation. Whose achieved figure misses its target by the most, and what explains it?', '["The static golden, because zero rate removes the friction group and leaves the whole of the closure error to the compressibility factor.", "BONNY-7, at 76633.1434 against 76631.2500, because it is the shallowest column and a short march accumulates the most error per foot.", "The deviated golden, because its elevation ratio is below one, so the depth it integrates over is not the depth its target was written on.", "FORCADOS-3, reading 138618.9944 against 138600.0000, and its friction group of 0.02721909 is the largest in the set."]'::jsonb, 3, 'That audit is published alongside the answer, so a march that has drifted can be caught without a second tool.'),
  ('nodal', 'intermediate', 'module', 'm04-the-gas-column', 8, 'What is wrong with evaluating the density group once at an average condition and pulling it outside the integral?', '["It is exact for a static column and only fails when flowing.", "It reverses the sign of the friction group, so the answer comes back high by roughly the same amount at every rate.", "It is a different published method rather than a cheap version of this one, and it lands near enough to survive a review.", "It cannot be evaluated at all without a converged march to supply the average."]'::jsonb, 2, 'It reads 735.658610 psia against a marched 735.995592 on BONNY-7, and 2626.370567 against 2608.360298 psia on FORCADOS-3.'),
  ('nodal', 'intermediate', 'module', 'm04-the-gas-column', 9, 'BONNY-7''s static injection column runs 0.01432765 psi/ft while its dead tubing at a 420 psia wellhead stands at 2570 psia. What does that contrast teach?', '["That the injection column has been computed on the wrong depth.", "Two columns in one hole an order of magnitude apart, so gas lift replaces a heavy fluid with a light one and does not push.", "That the gas column can be substituted for the tubing column wherever a quick estimate is wanted, since both are pressures in the same hole.", "That the tubing figure must already include friction, since no static column in a hole this deep could ever stand as high as 2570 psia."]'::jsonb, 1, 'Nearly seven thousand feet of gas is worth under a hundred psi, running from a 640 psia wellhead to 735.995592 psia.'),
  ('nodal', 'intermediate', 'module', 'm04-the-gas-column', 10, 'FORCADOS-3''s lift gas column reports 0.15674503 psi/ft. Why is quoting that as a static gradient wrong?', '["It carries 10.5 MMscf/d through 2.125 in at a friction group of 0.02721909, so most of that figure is friction.", "It was reported at 24 sub-intervals rather than at 256.", "It is quoted in psi per foot of measured depth while the column is deviated, so the elevation ratio has to be divided out before it can be compared.", "Its gas gravity of 0.61 differs from the tubing it is set beside, so the two gradients are written on different fluids."]'::jsonb, 0, 'A reported gradient is static only when the rate is zero, since zero rate is what makes the friction group vanish.'),
  ('nodal', 'intermediate', 'module', 'm04-the-gas-column', 11, 'A column''s gradient is back-calculated from its two ends. What do the midpoint pressures show about the profile between them?', '["The profile is straight, so the midpoints land on the chord.", "The profile sags below the chord, since pressure rises with depth faster than temperature eases it.", "The midpoints are noise, being within a psi of the straight line.", "It bows above the chord, 688.588305 psia against ends of 640 and 735.995592 psia, by under a psi and quite systematically."]'::jsonb, 3, 'On BONNY-7 the temperature change is proportionally larger than the pressure change, and the compressibility factor agrees at 0.93241456 averaged against 0.91517071 at the wellhead.'),
  ('nodal', 'intermediate', 'module', 'm04-the-gas-column', 12, 'The routine defaults to two sub-intervals. Is that a shortcut somebody left in?', '["Yes, and the published method has always used sixteen stations.", "Yes, the default was chosen for speed inside the node solver and has no standing in the literature.", "No, two sub-intervals with one interior station is precisely the published two station method as it was written.", "No, because two sub-intervals carry no truncation error of any kind."]'::jsonb, 2, 'Two intervals still carry a truncation error, and the size of that error belongs to the function being integrated rather than to the method''s standing.'),
  ('nodal', 'intermediate', 'module', 'm04-the-gas-column', 13, 'On one 8000 ft string with only the rate changed, the two station error reads -0.010380 psi at zero rate and -1.333117 psi at 9 MMscf/d. What kind of problem is it?', '["A gravity problem, growing with the weight of the column.", "A friction problem rather than a gravity one, nearly free on a static gradient and real once friction is comparable to gravity.", "A depth problem, since the same string integrated over a longer measured depth would show the same jump without any change in rate.", "A compressibility factor problem, worst where that factor sits furthest from one and the density group is therefore changing fastest with depth."]'::jsonb, 1, 'The error jumps rather than creeps, and down in the small friction region its sign is not even consistent, positive 0.006723 psi on one golden and negative 0.003223 on another.'),
  ('nodal', 'intermediate', 'module', 'm04-the-gas-column', 14, 'Why do two stations integrate a static column almost exactly and a friction loaded one badly?', '["A static column covers less of the string in effect, because with the friction group gone the march has only the weight term to carry down the hole.", "The static integrand is a smooth reciprocal of the density group, and a fitted straight line through its two end stations reproduces it to within rounding.", "The friction group makes each interval iterate more times before it closes, and every extra fixed point sweep adds a little more error to the total.", "Friction dominates near the top where the gas is thin and fast and gravity near the shoe, so the integrand changes character partway down."]'::jsonb, 3, 'Two stations have nothing to bend with, so they handle a slowly varying thing well and a sharply varying thing badly.'),
  ('nodal', 'intermediate', 'module', 'm04-the-gas-column', 15, 'Raising that step default would remove a quadrature error. Why is it an owner decision rather than a straightforward fix?', '["Because the higher step counts have never been gate tested, so nobody knows whether a finer march still reproduces the published targets.", "Because refining changes the physics of the column as well as the quadrature, so the goldens would have to be regenerated from scratch.", "It would move displayed bottomhole pressure in a shipped Suite app, and the present default is the published method itself.", "Because the error is a one sided bias, so a constant offset applied after the march would remove it more cheaply than more stations."]'::jsonb, 2, 'The alternative on the table is to keep the published method as the default and surface the step count in the interface instead.'),
  ('nodal', 'intermediate', 'module', 'm05-the-injection-pressure', 1, 'Gas enters an annulus at a known surface pressure and a valve sits at a known depth. What is the question the marching column exists to answer?', '["Whether the valve at that depth opens against its dome charge.", "What pressure the annulus side of that valve sees, from the surface pressure marched down the gas column.", "How much lift gas the well needs at that depth, since the injection rate follows from the pressure available.", "The tubing pressure opposite the valve, which is what the column marches down to the shoe."]'::jsonb, 1, 'Everything downstream is a comparison against it, including whether a compressor discharge setting is adequate thousands of feet below the wellhead.'),
  ('nodal', 'intermediate', 'module', 'm05-the-injection-pressure', 2, 'BONNY-7''s injection column gains under a hundred psi over 6700 ft while FORCADOS-3 more than doubles its 1080 psia. What accounts for most of that difference?', '["Depth alone, 9750 ft of true vertical against 6700 ft of it.", "The temperature profile, since FORCADOS-3 runs from 78 degF to 232 degF and hotter gas always weighs more per foot.", "Gas gravity, 0.66 against 0.61, which is a tenth of a difference in weight per foot.", "Friction, since FORCADOS-3 carries 10.5 MMscf/d for a friction group of 0.02721909 and BONNY-7 has no rate."]'::jsonb, 3, 'Its Reynolds number of 4321814.73 and Moody factor of 0.01603851 are what depth and gravity cannot substitute for.'),
  ('nodal', 'intermediate', 'module', 'm05-the-injection-pressure', 3, 'The annulus pressure at a valve depth is settled and auditable. What else does a designer need before saying the valve will open?', '["A dome charge corrected for temperature at depth, a port to bellows area ratio, and the tubing pressure there.", "Only the injection rate that the compressor can deliver.", "Nothing further, because annulus pressure at the valve depth is by itself the published opening criterion.", "The average compressibility factor the column reports, which sets the dome pressure."]'::jsonb, 0, 'The column supplies exactly one of those four, which is why an opening claim needs three inputs it never takes.'),
  ('nodal', 'intermediate', 'module', 'm05-the-injection-pressure', 4, 'Why is carrying FORCADOS-3''s 0.15674503 psi/ft across to a static annulus worse than applying a surface pressure at depth?', '["It is quoted at a different gas gravity, 0.66 against 0.61.", "It was taken along 11200 ft of deviated pipe, so a psi per foot from it cannot be laid against 6700 ft of vertical hole.", "Most of that figure is friction at 10.5 MMscf/d, so it invents hundreds of psi and errs on the optimistic side.", "It understates the pressure available, which is conservative but never declared."]'::jsonb, 2, 'Optimistic errors on injection pressure produce designs that do not unload, whereas the conservative slip merely wastes margin.'),
  ('nodal', 'intermediate', 'module', 'm05-the-injection-pressure', 5, 'One of the two columns in a lifted well changes shape when the rate changes. Which is it, and for what reason?', '["The annulus, because its friction group grows with the rate.", "The tubing, because a produced mixture lightens as rate rises, while the injection gas is already gas.", "Both equally, since raising a rate raises friction in any pipe and friction is what bends a curve in either column.", "Neither, since both are marched over the same measured depth at the same step count."]'::jsonb, 1, 'BONNY-7''s gravity share falls from 0.99999437 to 0.01413193 across its sampled rates, while its gas column stays put.'),
  ('nodal', 'intermediate', 'module', 'm05-the-injection-pressure', 6, 'The marching column and its closed form second opinion take gas rate in different units. What is the tell that the wrong one was handed over?', '["A friction group nowhere near 0.02721909 or 0.00182455, since a thousandfold slip lands it a million out.", "A column that fails to converge within its iteration limit, since a rate a thousandfold too large drives the fixed point past its band.", "A defining integral that no longer matches 18.75 times the gas gravity times the measured depth, which is the standing check.", "A midpoint pressure that sits below the straight line between the two ends, since too much friction makes a column sag rather than bow."]'::jsonb, 0, 'Nothing else warns you, because the column returns a converged and entirely confident number in silence.'),
  ('nodal', 'intermediate', 'module', 'm05-the-injection-pressure', 7, 'Weight and friction take different depths on a deviated injection column. Why will the defining integral check not catch a swap between them?', '["The check is only run after the column has already converged.", "The integral is evaluated at the midpoint alone, and on a deviated well the midpoint is the same in either depth measure.", "The two depths are close enough on any real deviation that the achieved figure moves by less than the psi unit the check is quoted in.", "The target is built from measured depth, so it agrees with itself whichever depth was used for the weight."]'::jsonb, 3, 'A swap leaves a column that is too heavy or whose friction is too small, and it fails silently in both directions.'),
  ('nodal', 'intermediate', 'module', 'm05-the-injection-pressure', 8, 'A column run hands back two pressures. Where does the second of them sit?', '["At the halfway point of the true vertical depth of the string.", "At whatever depth the caller asks for, since the routine returns a station array that can be read off at any point.", "At half of the measured depth, which on a deviated string is nowhere near half the true vertical drop.", "At the depth where the friction term first matches the weight of the gas above it, which is where a column is naturally split."]'::jsonb, 2, 'FORCADOS-3''s 1886.588368 psia therefore belongs to half of 11200 ft of pipe, not to half of its 9750 ft of vertical.'),
  ('nodal', 'intermediate', 'module', 'm05-the-injection-pressure', 9, 'FORCADOS-3 reads 1886.588368 psia at its midpoint against ends of 1080 and 2608.264008 psia. Why does that sit so far above the chord?', '["Weight acts hardest at the shoe and friction hardest at the top, so more than half the rise happens above.", "The midpoint has been taken at half of the true vertical depth.", "It was marched at twenty four sub-intervals rather than 256, so truncation lifts a middle station.", "The compressibility factor falls steadily with depth, which bends any column upward."]'::jsonb, 0, 'Departure from a straight line scales with the friction group, the same quantity that sets a two station truncation.'),
  ('nodal', 'intermediate', 'module', 'm05-the-injection-pressure', 10, 'The column is handed 10.5 MMscf/d and returns 2608.360298 psia. Where did that rate itself come from?', '["From the friction group of 0.02721909, since that group and the bore between them fix the rate the column was marched at.", "From the other side of the design, since the column takes the rate as an input and never selects it.", "From the tubing curve minimum, since the injection rate that lightens the column most is read off the bottom of the J.", "From the compressor discharge pressure, since what is available at the depth of the annulus is what sets the rate."]'::jsonb, 1, 'Sweeping BONNY-7''s lightening constant puts its tubing minimum at 561.403918, 627.069742, 646.294276 and 581.492476 stb/d, an optimisation with a turning point the column contributes one constraint to.'),
  ('nodal', 'intermediate', 'module', 'm05-the-injection-pressure', 11, 'What does the closed form cousin of the marching column hold at a single value?', '["The gas gravity and the Moody friction factor along the string.", "The friction group, evaluated once at the wellhead and carried unchanged to the shoe.", "The density of the gas, taken once at the midpoint conditions of the whole column.", "Temperature at the average of wellhead and shoe, and the compressibility factor at the average pressure."]'::jsonb, 3, 'With both constant the defining integral has a closed form, so it iterates on one scalar rather than down a column of stations.'),
  ('nodal', 'intermediate', 'module', 'm05-the-injection-pressure', 12, 'The averaged answer reads low on both columns with no rate and high on every column that flows. What does that ordering establish?', '["That the marched answer has not been refined far enough.", "That the truncation flips sign once the friction group passes the gravity term.", "A real assumption failing in a systematic way, since arithmetic slips do not sort themselves by rate.", "That the two routines disagree about the units in which the rate is supplied."]'::jsonb, 2, 'Holding the compressibility factor at one value asserts it is near linear in pressure, which a friction loaded integrand is furthest from.'),
  ('nodal', 'intermediate', 'module', 'm05-the-injection-pressure', 13, 'Two numbers out of one engine disagree. What single test says whether you have a truncation or two different methods?', '["Compare the size of the gap against a stated tolerance.", "Refine and watch: a gap that shrinks toward zero was truncation, a gap that settles is a method gap.", "Check the defining integral of each, since only the one carrying a truncation will miss its published target by a psi unit.", "Look at the sign of the gap, since a truncation reads low on every column while a method gap changes sign with rate."]'::jsonb, 1, 'Treat a method gap as a defect and you lose a day chasing nothing, and never average the two, which invents a third number from no published method.'),
  ('nodal', 'intermediate', 'module', 'm05-the-injection-pressure', 14, 'BONNY-7 produces 1355.714057 stb/d at 2062.142971 psia. What part did its injection column play in arriving at that figure?', '["None at all, since it comes from an inflow relation at 2.00000000 stb/d/psi meeting a tubing curve.", "It set the wellhead pressure the tubing curve was built at, since the annulus and the tubing share one surface pressure.", "It supplied the depth at which the annulus pressure crosses the tubing pressure, which is where the operating point was read.", "It fixed the drawdown of 677.857029 psi the well runs at under 2740 psia, which is what set the rate reported."]'::jsonb, 0, 'Gas lift does change production, by lightening the mixture and moving the tubing curve, but that is the tubing model''s work rather than the column''s.'),
  ('nodal', 'intermediate', 'module', 'm05-the-injection-pressure', 15, 'Why can a single column run never stand in for an unloading design?', '["The column cannot be run at more than one depth per well.", "The published method was derived for tubing rather than for an annulus, so it only ever approximates a stage of unloading.", "Unloading is a sequence of stages with their own pressures and valves, and a run is one snapshot.", "Unloading happens before the well flows, so there is no production rate to hand the column and nothing for it to march."]'::jsonb, 2, 'The stages run from the annulus level being pushed down to the valves above closing behind the injection point, and each has its own pressures.'),
  ('nodal', 'intermediate', 'module', 'm06-the-professional-reading', 1, 'The tier''s opening claim is that the tubing does not deliver a pressure. What does it do instead?', '["It reports the pressure the reservoir can supply at that rate.", "It converts a wellhead pressure into a rate, which is why an outflow curve is always read with rate on its vertical axis.", "It demands one, the bottomhole pressure needed to move a given rate up to a given wellhead pressure.", "It sets a ceiling on rate, above which the string will not pass any more fluid."]'::jsonb, 2, 'Sweeping that demand across rate is what produces the outflow curve, one half of a producing well.'),
  ('nodal', 'intermediate', 'module', 'm06-the-professional-reading', 2, 'BONNY-7''s tubing behaviour is carried by four constants. Which four?', '["A wellhead pressure of 420 psia, a gravity constant, a lightening constant and a friction constant.", "A depth, a tubing diameter, a roughness and a gas gravity.", "A productivity index, a reservoir pressure, a bubble point and an absolute open flow, which between them fix the whole curve.", "A wellhead pressure, a measured depth, a true vertical depth and a step count."]'::jsonb, 0, 'They are 2150 psi, 375 stb/d and 0.00064 psi per stb/d squared respectively, and nothing else is needed to build the curve.'),
  ('nodal', 'intermediate', 'module', 'm06-the-professional-reading', 3, 'One dead column stands at 2570 psia under a reservoir at 2740 psia, the other at 4310 psia above 3720 psia. What does that comparison foretell?', '["That the heavier column will produce at the lower rate.", "That the second well is the stronger, since a column standing above reservoir pressure carries more energy to surface.", "That the second well needs a smaller string to bring its dead column back under the reservoir.", "That one residual starts below zero and the other above it, which sets how many crossings are possible."]'::jsonb, 3, 'FORCADOS-3''s 590 psi of excess is what makes it the awkward teaching case and BONNY-7 the controlled one.'),
  ('nodal', 'intermediate', 'module', 'm06-the-professional-reading', 4, 'What gives an oil outflow curve its bottom?', '["The rate at which the reservoir can no longer supply the string.", "Weight falling with rate set against friction growing as its square, so the sum turns once friction wins.", "The point at which the column changes flow regime, which is where a multiphase correlation swaps one holdup relation for another.", "The wellhead pressure, which sets the floor that the whole of the curve rests upon."]'::jsonb, 1, 'BONNY-7''s gravity share runs from 0.99999437 at 4.32 stb/d down to 0.01413193 at 4324.44 stb/d, and the two terms cross at 968.379388 stb/d.'),
  ('nodal', 'intermediate', 'module', 'm06-the-professional-reading', 5, 'Double the sample count used to build a tubing curve. Which reported quantity moves most, and why?', '["The rate of the minimum, because the bowl is flat at its bottom, so a shift in rate costs very little pressure.", "The pressure at the loaded end, which is nearest the singular limit.", "The friction share at the highest sampled rate, since a doubled count raises the rate bound.", "The absolute open flow, which gets recomputed from the finer grid of sampled rates."]'::jsonb, 0, 'At 37 points BONNY-7 reads 604.341111 stb/d and 1477.003621 psia against 627.069742 stb/d and 1476.243252 psia refined, a gap of 22.728631 stb/d against 0.76036884 psi.'),
  ('nodal', 'intermediate', 'module', 'm06-the-professional-reading', 6, 'Wellhead pressures of 280, 350, 420 and 490 psia give minima of 1336.243252, 1406.243252, 1476.243252 and 1546.243252 psia. What motion is that?', '["The curve steepens on its friction limb and the bottom moves left, since back pressure is felt most where velocity is highest.", "The curve lifts and its minimum moves to a higher rate, because a higher back pressure needs more flow before friction can take over.", "The curve lifts by exactly the wellhead change and keeps its shape, the minimum staying at one rate.", "The curve lifts and flattens out, so the bottom becomes harder to locate and the reported rate drifts with the sample count."]'::jsonb, 2, 'All four minima sit at 627.069742 stb/d, which is the signature of a lever that adds a constant to every point of the curve.'),
  ('nodal', 'intermediate', 'module', 'm06-the-professional-reading', 7, 'Sweep the lightening constant through 187.50, 375.00, 750.00 and 1500.00 stb/d. What do the minima do?', '["Both the rate and the pressure rise steadily throughout, since a column that sheds weight more slowly turns later and higher.", "The rate climbs, turns at 646.294276 stb/d and falls back, while the pressure rises the whole way.", "The rate falls throughout while the pressure rises, which is the same motion that more friction produces on that curve.", "The rate holds at a single value while only the pressure of the minimum moves, which is what an additive lever does."]'::jsonb, 1, 'The four rates are 561.403918, 627.069742, 646.294276 and 581.492476 stb/d, so this is the one lever with a turning point in it.'),
  ('nodal', 'intermediate', 'module', 'm06-the-professional-reading', 8, 'Raise the friction constant of a tubing curve. Which way does its minimum travel?', '["Right and up, since more friction needs a higher rate before it can overtake the weight of the whole column.", "Left and down, because the same friction that steepens the rising limb also lightens the column faster on the falling one.", "It does not move at all, since friction acts only above the crossover rate, which the constant does not shift.", "Left and up, reaching 455.992990 stb/d and 1656.374688 psia once BONNY-7''s constant is doubled."]'::jsonb, 3, 'Halving it instead gives 845.667814 stb/d and 1309.348403 psia, so the bottom slides along the curve in both directions.'),
  ('nodal', 'intermediate', 'module', 'm06-the-professional-reading', 9, 'The single outflow model the engine owns runs from 952.986300 psia at 13.289296 Mscf/d to 1842.190804 psia at 13289.2963 Mscf/d. What shape is that?', '["Monotone, with no bottom in it at all, because a dry gas column has no liquid left to lighten.", "A J, with its bottom sitting at the lowest of the sampled rates.", "A J whose bottom lies off the left of the sampled window, which is why the reported minimum lands on the very first row.", "Almost flat, since the friction group of a gas column is far too small to bend a curve over that span of rate."]'::jsonb, 0, 'The reported minimum is a reduction over sampled rows, so it returns the first row and the engine flags that it did.'),
  ('nodal', 'intermediate', 'module', 'm06-the-professional-reading', 10, 'Two readings leave this tier carrying a number of their own. What must be stated beside a marched column pressure and beside a reported curve minimum?', '["The wellhead pressure that each of the two was built at.", "The convergence tolerance, the only setting that moves a reading once the physics is fixed.", "The step count for the column and the sample count for the curve, since each reading owns its resolution.", "The measured depth, which sets the friction of one and the weight of the other."]'::jsonb, 2, 'The two station default costs 0.01833744 psi on a gravity only column against 7.54108245 psi on a friction loaded one, so the count is part of the answer.'),
  ('nodal', 'intermediate', 'module', 'm06-the-professional-reading', 11, 'A closed form column disagrees with the marched one by 0.336981 psi on BONNY-7 and 18.010269 psi on FORCADOS-3. What are you looking at?', '["A truncation error, which sixteen sub-intervals would close.", "A method gap, since both are correctly implemented and refining one does not move it toward the other.", "A unit error, since the closed form takes its rate in Mscf/d and the marched column in MMscf/d, a thousandfold apart.", "A convergence failure on the heavier of the two columns, where the fixed point stops early at its iteration limit."]'::jsonb, 1, 'The averaged form reads high on any column carrying rate, so reporting it as the answer is one of the standard failures of this tier.'),
  ('nodal', 'intermediate', 'module', 'm06-the-professional-reading', 12, 'An injection column reports a pressure gradient of 0.15674503 psi/ft. What has to be quoted alongside it?', '["The true vertical depth, which the gradient was divided by.", "The average compressibility factor of 0.86007976, without which the gradient cannot become a weight.", "The wellhead temperature of 78 degF, which sets the density at the top of the string.", "The rate it was computed at, since most of it is friction and a static column of the same gas is far lighter."]'::jsonb, 3, 'BONNY-7''s static column runs at 0.01432765 psi/ft on the same physics, an order of magnitude apart on rate alone.'),
  ('nodal', 'intermediate', 'module', 'm06-the-professional-reading', 13, 'One of the two columns in this tier can be audited against a published target and the other cannot. Which, and against what?', '["The gas column, against a defining integral of 18.75 times the gas gravity times the measured depth.", "The tubing curve, against its own dead column at zero rate.", "The tubing curve, against the absolute open flow, which bounds it from above and is published for each inflow family.", "The gas column, against the average temperature and average compressibility answer, which is published alongside it."]'::jsonb, 0, 'The tubing curve has no defining integral, no published target and no convergence study, which is the price of taking it as an input.'),
  ('nodal', 'intermediate', 'module', 'm06-the-professional-reading', 14, 'BONNY-7 reads 2545.501142 psia at its loaded end against a dead column standing at 2570 psia. What does putting the two together check?', '["That the sample count is fine enough at the loaded end.", "That the friction end is consistent, since the two ends of a curve bracket the dead column.", "That the smallest flowing rate has already lightened the column slightly, so the end sits just under it.", "That the wellhead pressure of 420 psia was entered into both of the two models."]'::jsonb, 2, 'FORCADOS-3 reads higher at its loaded end than at its friction end, so one end of a curve never checks the other.'),
  ('nodal', 'intermediate', 'module', 'm06-the-professional-reading', 15, 'Why does this tier stop short of taking an intersection?', '["The engine has no node solver until the next tier adds one.", "A node solved on a curve you cannot vouch for is an intersection rather than an answer to anything.", "The inflow relation belongs to the tier below, and the two halves are never held in one study until the tier above.", "An intersection needs both curves sampled at the same rates, and the two sample counts are set independently."]'::jsonb, 1, 'A well of the FORCADOS-3 kind has two crossings with only one held, so an intersection returned without its residual is not yet a verdict.'),
  ('nodal', 'intermediate', 'final', null, 1, 'Two contractors deliver outflow curves for one well, and one of them computed its wellhead term from a gauge reading. What does the node engine do with the pair?', '["It rejects the gauge based curve at the first sample row.", "It rescales the lower curve onto the higher before the solver sees them, so the offset drops out.", "It solves both with equal confidence, because nothing in it validates an injected curve against anything.", "It flags the pair as inconsistent once their minima disagree by more than a psi."]'::jsonb, 2, 'A curve computed in psig is wrong by one atmosphere at every rate, and because the wellhead term is additive that error never cancels.'),
  ('nodal', 'intermediate', 'final', null, 2, 'A workover proposal for BONNY-7 rests on a large friction term. At which of its sampled rates does upsizing the string attack the larger half of the bill?', '["At 1924.38 stb/d, where the gravity share has fallen to 0.12887773 and friction carries the rest.", "At 484.34 stb/d, where the gravity share reads 0.86205504.", "At every rate on the axis, since friction is an unbounded square law and therefore the dominant term wherever the well is produced.", "At the loaded end of the axis, where the demand of 2545.501142 psia stands higher than at any other sampled rate."]'::jsonb, 0, 'Friction overtakes gravity on BONNY-7 at 968.379388 stb/d, so the same remedy is the wrong one a few hundred stb/d lower down.'),
  ('nodal', 'intermediate', 'final', null, 3, 'High velocity gas near the top of a string is where density changes fastest. Which term is missing there, and why can the shortfall not be quantified from the output?', '["The elevation group, which the integrand drops once turbulent.", "The friction group, which the published integrand carries but this implementation suppresses once the flow is fully turbulent.", "The slip term, which is reported separately as a holdup correction and can be added back.", "The acceleration loss, which neither instrument computes, so the deficit is never reported anywhere."]'::jsonb, 3, 'Dropping a term and forgetting one look identical in the output, which is why the omission has to be stated rather than detected.'),
  ('nodal', 'intermediate', 'final', null, 4, 'The reservoir is recalibrated and the absolute open flow falls, while nothing at all is done to the string. What happens to the tubing curve?', '["It is unchanged, since the tubing constants set the whole curve.", "It is redrawn at a different spacing, so its sampled minimum can shift although no tubing property moved.", "It keeps its sampled minimum exactly, since a reduction returns the smallest pressure found and pressure does not depend on the grid.", "It shifts vertically by the size of the change in open flow, keeping the bottom of the curve at the very same rate."]'::jsonb, 1, 'The rate bound of a tubing curve is the absolute open flow, so the horizontal axis is inherited from the inflow rather than from the string.'),
  ('nodal', 'intermediate', 'final', null, 5, 'Two consumers of the same engine report different flowing pressures for one well, and each is internally consistent. What has happened?', '["Each supplied its own traverse, and the engine defends neither because it never asked what produced them.", "One of them left the sample count off its tubing curve.", "One of them ran past its rate bound, where the curve is arithmetic about an unreachable state.", "The solver returned a different intersection each time from the very same pair of curves."]'::jsonb, 0, 'The Suite alone marches Beggs and Brill, Hagedorn and Brown, Gray or Fancher and Brown, four defensible methods for one job.'),
  ('nodal', 'intermediate', 'final', null, 6, 'A summary sheet quotes 12560.087474 psia for BONNY-7 as evidence the string is undersized, beside a reservoir holding 2740 psia. What is the objection?', '["The figure was read off the wrong well''s curve entirely.", "The figure omits the wellhead pressure, which is additive and must be added back before any comparison with reservoir pressure.", "That row correctly evaluates a rate the well can never reach, so it belongs in the plot and not a report.", "The demand ought to be compared against the drawdown at that rate rather than against the static reservoir pressure."]'::jsonb, 2, 'At 4324.44 stb/d the friction term alone is 11968.524642 psi, which is why the far right of that curve climbs into five figures.'),
  ('nodal', 'intermediate', 'final', null, 7, 'An engineer argues that the engine should simply hardcode one multiphase correlation and be done with it. What is the module''s own objection?', '["A hardcoded correlation would slow every node solve down.", "A hardcoded correlation cannot close a defining integral, so every reading off it is unauditable.", "The engine owns no PVT stack, so it could not evaluate any such correlation at all.", "Four defensible methods exist for the job, so choosing one asserts an invisible judgement it cannot defend."]'::jsonb, 3, 'Cullender and Smith needs nothing but a compressibility factor, which is why the dry gas column is the one the engine is willing to own.'),
  ('nodal', 'intermediate', 'final', null, 8, 'A loading floor for BONNY-7 is set at the crossover rate of 968.379388 stb/d. Which way is that floor wrong, and by what reasoning?', '["Hundreds of stb/d low, since the crossover always precedes the bottom.", "Hundreds of stb/d high, because the bottom sits at 627.069742 stb/d where slopes cancel and not values.", "It is correct, because the curve turns exactly where the falling gravity term and the rising friction term become equal in size.", "It is wrong only on FORCADOS-3, whose crossover rate and the bottom of its curve happen to coincide exactly."]'::jsonb, 1, 'FORCADOS-3 makes the same point harder, its gravity share still reading 0.75175383 at the bottom of its own curve.'),
  ('nodal', 'intermediate', 'final', null, 9, 'A margin is placed a little above BONNY-7''s sampled bottom of 604.341111 stb/d. Where does it sit against the true turn at 627.069742 stb/d?', '["Above it, because sampling always reads the bottom of a bowl low.", "Exactly on it, since the pressure gap between the two readings is under a psi and the rate gap therefore cannot matter to a margin.", "Safely to the right of it, because the sampled rate is the larger of the two.", "Below it and on the falling limb, which is the single place a loading floor must never be placed."]'::jsonb, 3, 'Sampling cannot land below the bottom of a bowl, so the reported pressure always reads high while the rate can fall on either side.'),
  ('nodal', 'intermediate', 'final', null, 10, 'FORCADOS-3 gives four consecutive samples inside a few tens of psi of one another. What does that flatness do to the two halves of its reported minimum?', '["It leaves the minimum pressure trustworthy while making the rate the least reliable figure on the curve.", "It makes both halves equally uncertain across the sweep.", "It makes the rate trustworthy and the pressure fragile, since a flat region pins the position while leaving the height free to wander.", "It removes the bottom of the curve altogether, so the reduction simply hands back whichever row was sampled first."]'::jsonb, 0, 'The rate gaps on the two teaching wells are 22.728631 and 31.814966 stb/d against pressure gaps of 0.76036884 and 0.25586360 psi.'),
  ('nodal', 'intermediate', 'final', null, 11, 'Only the sample count is changed between two runs of a wellhead pressure study. Which readings can move, and which cannot?', '["Nothing moves, since the grid is anchored to the same rates.", "Everything moves, since the sample count sets the rate bound and so the whole rate axis.", "The minimum rate and pressure can both shift, while the step between wellhead cases stays exact.", "Only the minimum pressure can move, the minimum rate being fixed by the constants."]'::jsonb, 2, 'A wellhead change is additive and blind to rate, so its effect is exact whatever grid the curve happened to be drawn on.'),
  ('nodal', 'intermediate', 'final', null, 12, 'One well climbs to five figures past its bottom while the other ends below where it started. Which will be the quiet one to operate?', '["The one that climbs steeply, since the size of the restoring force is what a deep J is measuring.", "The one ending below its start, which has more room to run.", "Neither can be ranked from the shape alone, because the restoring force belongs to the reservoir''s statement rather than the tubing''s.", "The one with the wider falling limb, since that is the part of the axis where the demand on the string is lowest."]'::jsonb, 0, 'BONNY-7 runs from 1476.243252 psia at its bottom out to 12560.087474 psia, where FORCADOS-3 only reaches 3310.421637 psia.'),
  ('nodal', 'intermediate', 'final', null, 13, 'A reduction over rows always returns a row. On which curve does it return a minimum that is not a feature of the well?', '["On any tubing curve that was sampled at fewer than 25 points.", "On FORCADOS-3, whose bowl is so shallow that four consecutive samples share a pressure and no genuine turning point exists.", "On any curve whose rate bound was inherited from a recently recalibrated inflow.", "On the monotone dry gas curve, whose reported bottom is nothing more than the lowest sampled rate."]'::jsonb, 3, 'That minimum sits at a thousandth of the span and moves by exactly one sample spacing when only the sample count is changed.'),
  ('nodal', 'intermediate', 'final', null, 14, 'A well sitting left of its bottom suffers a small fall in rate. Trace what follows and name the force that is missing.', '["Demand falls, so the rate recovers on its own within minutes.", "Demand rises, rate falls further and the column loads, friction being too small there to push back.", "Demand rises and the reservoir answers by raising its own delivery, which restores the original rate through the productivity index.", "Demand is unchanged, because the two terms cancel each other exactly across the whole of the falling limb."]'::jsonb, 1, 'The rising friction limb is the only restoring force the tubing has, which is why the gentle J of FORCADOS-3 wanders.'),
  ('nodal', 'intermediate', 'final', null, 15, 'A separator pressure is entered where a tubing head pressure belongs. What does that do to the demand and to the reported bottom?', '["It overstates the demand and moves the bottom to a lower rate.", "It understates the demand most at high rate, where the omitted choke and flowline losses are largest, dragging the bottom outward.", "It understates the demand by a fixed amount at every rate and leaves the minimum rate exactly where it was.", "It leaves the curve untouched, since the two pressures differ only by a constant."]'::jsonb, 2, 'Choke and flowline losses appear nowhere in this curve, so the substitution is silent and the finished shape stays entirely plausible.'),
  ('nodal', 'intermediate', 'final', null, 16, 'A string is upsized to cut demand at today''s rate on a well expected to decline for years. What has that design bought and built in?', '["A lower demand now, with no change to the loading threshold.", "A lower demand now, and a bottom slid out to 845.667814 stb/d that decline will eventually walk into.", "A lower demand now, and a bottom pulled back to a smaller rate, which widens the band of rising limb the well can be produced on.", "A higher demand at today''s rate, bought against a loading threshold that has moved the right way for once."]'::jsonb, 1, 'A real bore change also alters velocity, then slip, then holdup, so the column gets heavier and the instrument carries half the mechanism.'),
  ('nodal', 'intermediate', 'final', null, 17, 'Rising water cut walks a well from BONNY-7''s condition towards FORCADOS-3''s. Why is the operational change not gradual?', '["Once the dead column passes reservoir pressure the well stops restarting itself and needs an intervention.", "Because the gravity constant rises faster than water cut does.", "Because the lightening constant falls with water cut, dropping the bottom of the curve onto a rate the well is already below.", "Because the friction constant is moving with scale and wax at the very same time."]'::jsonb, 0, 'BONNY-7''s dead column sits 170 psi under its reservoir pressure and FORCADOS-3''s stands 590 psi over, and water cut crosses that line.'),
  ('nodal', 'intermediate', 'final', null, 18, 'Three different stories are told from three pairs taken out of one lightening constant sweep. What discipline prevents that?', '["Take the two widest points, which bracket the whole response.", "Average the three pairs, since the turning point is an artefact of the grid and disappears once the sweep is resampled finely.", "Quote only the pressure column of the sweep, since that is its monotone half while the rate column turns inside the range.", "Sweep rather than difference, and report the level with the threshold, since the lever turns inside its range."]'::jsonb, 3, 'BONNY-7''s minimum rate climbs to 646.294276 stb/d and turns back to 581.492476 stb/d while its minimum pressure rises throughout.'),
  ('nodal', 'intermediate', 'final', null, 19, 'Two low gas injection rates are fitted with a straight line to model a well''s response. What has that model thrown away?', '["The gravity budget, which is unbounded and dominates late.", "Nothing, since the two effects are of opposite sign and comparable size, so their sum is linear in injection rate throughout.", "The quadratic friction penalty, which is why the fitted response carries no turning point at all.", "The wellhead pressure, which rises with injection rate and lifts the whole curve."]'::jsonb, 2, 'The reverse error is as common, a flattening response read as an optimum when it can equally be two effects approaching cancellation.'),
  ('nodal', 'intermediate', 'final', null, 20, 'Gas lift is proposed for BONNY-7 because its pressure drop at high rate is large. Why does the gravity share argue against it?', '["At 1924.38 stb/d that share is 0.12887773, so lift attacks a small term and feeds the large one.", "Because BONNY-7''s dead column already outweighs its reservoir.", "Because its lightening constant of 375 stb/d is already the lower of the two, leaving no further weight in the column to shed.", "Because gas lift raises the wellhead pressure that the separator sitting downstream of the choke has to hold."]'::jsonb, 0, 'FORCADOS-3 is the candidate instead, still at 0.53444210 by 2586.52 stb/d with a dead column 590 psi above its reservoir pressure.'),
  ('nodal', 'intermediate', 'final', null, 21, 'A curve arrives lifted bodily with its bottom at the same rate as before. Which lever was moved, and how can you be sure?', '["The friction constant, which acts only on the rising limb.", "The wellhead, since only a rate blind additive change leaves every slope on the curve untouched.", "The lightening constant, whose sweep holds the minimum rate inside a narrow band while lifting the minimum pressure monotonically.", "The tubing bore, which moves the level by five powers and the bottom not at all."]'::jsonb, 1, 'The dead column moves one for one with it, running 2430, 2500, 2570 and 2640 psia across the four cases on BONNY-7.'),
  ('nodal', 'intermediate', 'final', null, 22, 'An auditor calls the two sub-interval default a shortcut left in the code. Correct that, and say where it costs almost nothing.', '["It is exactly the published two station method, and on a gravity only column it costs 0.01833744 psi.", "It is a debug setting nobody removed, and it costs nothing below 4 MMscf/d, where the friction group is too small to bend the column.", "It is a shortcut, but a harmless one, since the Simpson closure makes the march exact on any column with a linear temperature profile.", "It is the published method, and it costs nothing at all on any column that happens to be drilled vertical."]'::jsonb, 0, 'The same default costs 7.54108245 psi on FORCADOS-3, whose friction group of 0.02721909 is the largest in the course.'),
  ('nodal', 'intermediate', 'final', null, 23, 'Two numbers for FORCADOS-3''s annulus disagree. One gap closes under refinement and one settles. Identify each and say what a report must carry.', '["Both are truncation, so a single step count settles the pair.", "Both are method gaps, refinement moves neither, and the only honest report is their average.", "The step count gap is truncation and closes, the closed form gap does not, so state the count and the method.", "The closed form gap closes under refinement, while the step count gap settles."]'::jsonb, 2, 'FORCADOS-3 reads 2600.819216 psia at two sub-intervals against 2608.360298 at 256, and 2626.370567 psia from the closed form.'),
  ('nodal', 'intermediate', 'final', null, 24, 'A gas lift design borrows 0.15674503 psi/ft to size a static annulus on another well. Name the two separate errors in that.', '["It was measured on a vertical column and applied to a deviated one, where a gradient per foot of measured depth overstates the weight carried.", "It came from a marched column rather than the closed form cousin, and it was quoted without the step count the march was run at.", "It is a local gradient taken at the shoe of one column and then applied across the whole length of another.", "Most of it is friction at 10.5 MMscf/d, and even a correct average is wrong at an intermediate depth."]'::jsonb, 3, 'BONNY-7''s genuinely static column gains 0.01432765 psi/ft, under a hundred psi over 6700 ft, an order of magnitude apart.'),
  ('nodal', 'intermediate', 'final', null, 25, 'A reader takes the compressibility factor falling from 0.98086541 to 0.88010263 and climbing to 0.97569737 as a pressure trend. What went wrong?', '["The rows are quoted at four different gas rates, not four pressures.", "Pressure, temperature and gas gravity all move together across those rows, so it is a range and not a trend.", "The factor does not depend on pressure in this correlation, only on gas gravity and temperature.", "The rows are drawn from two different published correlations for that factor."]'::jsonb, 1, 'Nothing is held constant across those four published conditions, so a reader who takes the dip for a pressure effect has read three variables as one.'),
  ('nodal', 'intermediate', 'final', null, 26, 'An outflow study is run on the default column because the injected curve was never wired up, and its minimum is quoted as physical. What gives it away?', '["The minimum pressure is quoted without the step count of the march that produced it, so its truncation error cannot be bounded by the reader.", "The minimum lies in the interior of the range and hardly moves when the sample count is doubled, which no genuine J ever does.", "The minimum sits at the very first sample and moves by one spacing when only the count is changed.", "The curve carries no friction term of any kind, so it runs perfectly flat across the whole of its rate axis."]'::jsonb, 2, 'Nothing in Cullender and Smith lightens with rate, so the built-in column rises monotonically from 952.986300 psia to 1842.190804 psia.'),
  ('nodal', 'intermediate', 'final', null, 27, 'A well makes a trace of condensate and its temperature survey is not a straight line. How does the marching column respond, and what does its audit say?', '["It notices neither, returns a converged answer, and its defining integral still closes against the target.", "It refuses to run and reports an unsupported temperature profile.", "It switches to the closed form cousin, which tolerates both, and flags the substitution in the average compressibility factor.", "It converges but fails its defining integral, which is how the case is caught."]'::jsonb, 0, 'The method is dry gas only, will not take a profile that is anything but linear in measured depth, and marches downward only.'),
  ('nodal', 'intermediate', 'final', null, 28, 'A report quotes 2600.819216 psia for FORCADOS-3''s annulus and states no step count. Why does that survive review, and what is lost?', '["It is implausible on its face, standing further from the converged column than the closed form does, so review should have caught it.", "It is high rather than low, since fewer stations overestimate a column, so the reader loses the direction of the error too.", "It is exact at the stated depth, and all the reader loses is the midpoint pressure of the column above it.", "It is plausible for that well and low by 7.54108245 psi, an error nothing in the number itself shows."]'::jsonb, 3, 'The converged value is 2608.360298 psia, and the two station error falls roughly as the square of the step count on the way there.'),
  ('nodal', 'intermediate', 'final', null, 29, 'A design states that the annulus holds 735.995592 psia at 6700 ft, therefore the valve opens, therefore the well lifts from there. Where does it fail?', '["At the first step, since that pressure cannot be audited.", "At the third step only, because a valve that opens at a stated depth always establishes the injection point for the whole well.", "Nowhere at all, provided that the column was marched at a properly stated step count.", "At the second step, and the failure is invisible because the pressure itself is correct and auditable."]'::jsonb, 3, 'A dome charge, its temperature correction at depth, a port to bellows area ratio and the tubing pressure there are all still wanted.'),
  ('nodal', 'intermediate', 'final', null, 30, 'A friction group returns a million times away from the published magnitudes. What happened, and why did nothing complain?', '["The gas rate went in under the other routine''s units, and the march converges confidently regardless.", "The roughness was entered in feet rather than as a fraction of the bore, and nothing in the march checks the bound on that group.", "The two depths were swapped, which rescales the friction group by the elevation ratio and is never flagged by the integral audit.", "The rate was squared twice inside the friction group, a slip that no published gate in the engine tests for."]'::jsonb, 0, 'The marching column takes MMscf/d and the closed form cousin Mscf/d, and the group carries rate squared, so the two differ by a million.'),
  ('nodal', 'intermediate', 'final', null, 31, 'FORCADOS-3''s midpoint pressure is read as the pressure at half its true vertical depth. Why is that among the hardest errors to catch?', '["It is a wrong pressure at the right place, so it reads oddly.", "It fails the defining integral on a deviated well, so a vertical column hides it.", "It is a real pressure at the wrong place, half of 11200 ft of pipe rather than half of 9750 ft.", "It doubles the friction group, which grows as the square of the marched depth."]'::jsonb, 2, 'The march runs over measured depth with its stations evenly spaced in it, and the count rounds up to an even number for the Simpson closure.'),
  ('nodal', 'intermediate', 'final', null, 32, 'Shallow unloading valves are placed by interpolating linearly between an injection column''s two ends. Which way does that read?', '["High in the upper half on every column the course carries, since the gas grows denser with depth and the true column sits under the chord.", "Low in the upper half, badly on a high friction column and by a fraction of a psi on a static one.", "Correct everywhere, because the returned gradient is back-calculated from the two ends and therefore reproduces the chord exactly.", "Low in the lower half of the column, where the gas is densest and its weight makes the largest contribution."]'::jsonb, 1, 'Departure from a straight line scales with the friction group, the same quantity that sets the truncation of a two station march.'),
  ('nodal', 'intermediate', 'final', null, 33, 'A reviewer proposes averaging the marched and the closed form answers to settle an annulus pressure. What is the objection?', '["The average is a third number from no published method, where the marched answer has a step count.", "The average is fine once both were run at 256 sub-intervals.", "The two answers are one method at two resolutions, so their average beats either alone.", "The closed form is by some way the more reliable of the two on a flowing column."]'::jsonb, 0, 'Both are published, both correctly implemented, and each is an exact solution of its own statement of the problem.'),
  ('nodal', 'intermediate', 'final', null, 34, 'One well carries two different rates and a report names only the rate. What has the reader lost?', '["Only the units, which can be recovered from the magnitude, since a gas injection rate and a liquid production rate never overlap in size.", "The step count, which is the only quantity a marched column needs beside its answer and cannot be recovered from a rate.", "Which of the two models the figure belongs to, injection being in MMscf/d and production in stb/d.", "The direction of each march, which runs downward on the first of the two models and upward on the second."]'::jsonb, 2, 'Sorting the conditions into two models before anything is computed is how that collision is caught rather than discovered later.'),
  ('nodal', 'intermediate', 'final', null, 35, 'There is a depth below which an annulus loses the race to the tubing beside it. What produces that crossover?', '["The two columns share a surface pressure but not a temperature.", "The gas column gains almost nothing with depth while the liquid column beside it gains a great deal.", "The annulus carries friction and the tubing does not, so it loses ground with valve depth.", "The annulus is marched downward while the tubing curve is swept upward in rate."]'::jsonb, 1, 'BONNY-7 reaches 735.995592 psia at 6700 ft against a tubing standing at 2570 psia dead and flowing at 2062.142971 psia.'),
  ('nodal', 'intermediate', 'final', null, 36, 'Conditions for a graded outflow problem arrive as one list, and the first task is to sort them into two models. What does sorting catch early?', '["That the two models share their depths, so one measured depth and true vertical depth pair serves the curve and the column alike.", "That two of the rates are quoted in different units, MMscf/d for the column and stb/d for the curve.", "That the wellhead pressure of the tubing curve and the surface pressure of the injection column must be the same number.", "That the sample count of the curve and the step count of the column are really one and the same quantity."]'::jsonb, 1, 'The tubing curve takes four constants and a rate range, and the gas column takes its own list including both depths and a step count.'),
  ('nodal', 'intermediate', 'final', null, 37, 'Which check would catch a mistyped gravity constant on a tubing curve, and what does it compare?', '["The defining integral, compared against its published target.", "The loaded end against the friction end, since the two must stand at comparable heights on any curve with a genuine bottom.", "The two terms near the bottom, since a minimum far from its crossover means a constant is wrong.", "The sampled minimum against a finely resampled one taken at 20001 points."]'::jsonb, 2, 'BONNY-7''s terms cross at 968.379388 stb/d against a minimum at 627.069742 stb/d, so the two sit a few hundred stb/d apart.'),
  ('nodal', 'intermediate', 'final', null, 38, 'A reviewer sanity checks every tubing curve by requiring the friction end to stand above the loaded end. Where does that rule break?', '["On FORCADOS-3, which reads 4293.189726 psia loaded against 3310.421637 psia at its friction end.", "On BONNY-7, whose loaded end sits under its dead column, so the rule compares the friction end against a pressure the well never holds.", "On the built-in dry gas column, whose reported minimum is its first row and whose two ends cannot be compared at all.", "On any tubing curve whose sample count differs from that of the other curve it is being compared against."]'::jsonb, 0, 'Where the bottom sits relative to the rate bound decides which end stands higher, so one end can never be used to check the other.'),
  ('nodal', 'intermediate', 'final', null, 39, 'A solver returns the first intersection it finds on a well whose dead column outweighs its reservoir. Which crossing is that?', '["The upper one, at 2125.009203 stb/d, which the well can hold.", "The one at the tubing minimum, which a sign change scan meets before either crossing.", "Neither of them, because a residual that starts positive can have no crossing.", "The lower one, at 234.488087 stb/d, which is the heading branch rather than the operating point."]'::jsonb, 3, 'FORCADOS-3''s pair leaves a stable window 1890.521117 stb/d wide, with the operating point at 2125.009203 stb/d and 2366.909222 psia.'),
  ('nodal', 'intermediate', 'final', null, 40, 'Raising a node scan from 40 grid points to 50 turns a flowing well into a dead one. What changed, and what should be read instead?', '["The stability slope test failed first, the tubing curve rising faster than the inflow falls at the crossing, so the well is truly dead.", "The tubing curve was resampled along with the scan, which moved its minimum rate and closed the window between the crossings.", "No interval straddles the dip any more, so read the residual and its sign rather than the picture.", "The finer scan turned up a third crossing, which the solver then quietly discards under a rule of its own."]'::jsonb, 2, 'FORCADOS-3 choked to 1469.15 psia at the wellhead has a true window of 57.851719 stb/d, which 40 points find, 50 lose and 60 find again.'),
  ('nodal', 'intermediate', 'final', null, 41, 'A second curve arrives in the next tier and an intersection is taken. Which of this tier''s cautions stay in force?', '["None, since an intersection replaces every reading taken here.", "All of them, the minimum still a reduction over samples and the column still needing its step count.", "Only the sampling caution, since the injection column is not used once the curves cross.", "Only the caution about the two ends, which the node''s rate bound now fixes."]'::jsonb, 1, 'A node solved on a curve you cannot vouch for is an intersection rather than an answer, which is why this tier stops before taking one.'),
  ('nodal', 'intermediate', 'final', null, 42, 'Among the failures this tier warns about, which one survives every check available, and why?', '["Mixing MMscf/d with Mscf/d, which no magnitude check can see.", "Leaving the step count off a marched pressure, which the defining integral cannot detect because it closes at every count.", "Reporting the closed form as the answer, which reads high on any flowing column.", "Swapping measured and true vertical depth, since the integral target is built from measured depth."]'::jsonb, 3, 'The target is 18.75 times the gas gravity times the measured depth, so it agrees with itself whichever way the two depths were entered.');
